// Starts blitz-lsp and asks it for everything the extension uses, without an editor:  node lsp_smoke.js <blitz-lsp> [commands.txt]
'use strict';
const { spawn } = require('child_process');
const fs = require('fs');
const os = require('os');
const path = require('path');
const assert = require('assert');

const exe = process.argv[2];
if (!exe) { console.error('usage: lsp_smoke.js <blitz-lsp> [commands.txt]'); process.exit(2); }
const env = Object.assign({}, process.env);
if (process.argv[3]) env.BLITZLLVM_COMMANDS = process.argv[3];

const child = spawn(exe, ['--stdio'], { stdio: ['pipe', 'pipe', 'inherit'], env });
let buffer = Buffer.alloc(0);
const waiting = new Map();
const notifications = [];
let nextId = 1;

child.stdout.on('data', (chunk) => {
  buffer = Buffer.concat([buffer, chunk]);
  for (;;) {
    const end = buffer.indexOf('\r\n\r\n');
    if (end < 0) return;
    const match = /Content-Length: (\d+)/i.exec(buffer.slice(0, end).toString());
    const length = Number(match[1]);
    if (buffer.length < end + 4 + length) return;
    const message = JSON.parse(buffer.slice(end + 4, end + 4 + length).toString('utf8'));
    buffer = buffer.slice(end + 4 + length);
    if (message.id !== undefined && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id); }
    else notifications.push(message);
  }
});

function send(message) {
  const body = Buffer.from(JSON.stringify(Object.assign({ jsonrpc: '2.0' }, message)), 'utf8');
  child.stdin.write(`Content-Length: ${body.length}\r\n\r\n`);
  child.stdin.write(body);
}
function request(method, params) {
  const id = nextId++;
  return new Promise((resolve) => { waiting.set(id, resolve); send({ id, method, params }); });
}
const notify = (method, params) => send({ method, params });
async function diagnosticsFor(uri) {
  for (let i = 0; i < 200; i++) {
    const found = notifications.filter((n) => n.method === 'textDocument/publishDiagnostics' && n.params.uri === uri);
    if (found.length) { const last = found[found.length - 1]; notifications.length = 0; return last.params.diagnostics; }
    await new Promise((r) => setTimeout(r, 25));
  }
  throw new Error('no diagnostics');
}

const source = [
  'Type Player',
  '\tField name$',
  '\tField score',
  'End Type',
  '',
  'Global total = 0',
  'Const MAX = 10',
  '',
  'Function Add(a, b)',
  '\tLocal result = a + b',
  '\tReturn result',
  'End Function',
  '',
  '.start',
  'Local p.Player = New Player',
  'p\\score = Add(1, 2)',
  'total = total + p\\score',
  'Print "x" + total',
  ''
].join('\n');

const position = (text, needle, nth = 0, delta = 0) => {
  let at = -1;
  for (let i = 0; i <= nth; i++) at = text.indexOf(needle, at + 1);
  assert(at >= 0, 'missing ' + needle);
  const before = text.slice(0, at + delta);
  const lines = before.split('\n');
  return { line: lines.length - 1, character: lines[lines.length - 1].length };
};
const applyEdits = (text, edits) => {
  const offset = (p) => { const lines = text.split('\n'); let o = 0; for (let i = 0; i < p.line; i++) o += lines[i].length + 1; return o + p.character; };
  return edits.slice().sort((a, b) => offset(b.range.start) - offset(a.range.start))
    .reduce((t, e) => t.slice(0, offset(e.range.start)) + e.newText + t.slice(offset(e.range.end)), text);
};

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'blitz-lsp-'));
  const file = path.join(dir, 'main.bb');
  fs.writeFileSync(file, '');
  // A program of two files, and another program in the same folder that must not be touched by a rename
  fs.writeFileSync(path.join(dir, 'lib.bb'), 'Global shared = 1\nFunction Helper()\n\tReturn shared\nEnd Function\n');
  fs.writeFileSync(path.join(dir, 'other.bb'), 'Global shared = 2\nPrint shared\n');
  const uri = 'file://' + file;
  let result = await request('initialize', { processId: null, rootUri: 'file://' + dir, capabilities: {}, initializationOptions: { warningLevel: 3 } });
  for (const c of ['hoverProvider', 'definitionProvider', 'renameProvider', 'documentFormattingProvider', 'documentSymbolProvider', 'codeActionProvider'])
    assert(result.result.capabilities[c], c);
  notify('initialized', {});
  notify('textDocument/didOpen', { textDocument: { uri, languageId: 'blitzbasic', version: 1, text: source } });

  // Diagnostics: a correct program has no errors.
  let diagnostics = await diagnosticsFor(uri);
  assert.deepStrictEqual(diagnostics.filter((d) => d.severity === 1), [], JSON.stringify(diagnostics));

  // Symbols
  result = await request('textDocument/documentSymbol', { textDocument: { uri } });
  const names = result.result.map((s) => s.name);
  for (const n of ['Player', 'Add', 'total', 'MAX', 'start']) assert(names.includes(n), `symbol ${n} in ${names}`);
  assert.deepStrictEqual(result.result.find((s) => s.name === 'Player').children.map((c) => c.name), ['name', 'score']);

  // Hover: a command and a function of the program
  result = await request('textDocument/hover', { textDocument: { uri }, position: position(source, 'Print', 0, 1) });
  assert(/Print\(/.test(result.result.contents.value), JSON.stringify(result));
  result = await request('textDocument/hover', { textDocument: { uri }, position: position(source, 'Add(1', 0, 1) });
  assert(/Function Add\(a, b\)/.test(result.result.contents.value), JSON.stringify(result));

  // Definition: the call goes to the function, the local to its Local
  result = await request('textDocument/definition', { textDocument: { uri }, position: position(source, 'Add(1', 0, 1) });
  assert.strictEqual(result.result[0].range.start.line, 8);
  result = await request('textDocument/definition', { textDocument: { uri }, position: position(source, 'Return result', 0, 8) });
  assert.strictEqual(result.result[0].range.start.line, 9);

  // Completion
  result = await request('textDocument/completion', { textDocument: { uri }, position: { line: 0, character: 0 } });
  const labels = result.result.items.map((i) => i.label);
  for (const l of ['While', 'Print', 'Add', 'Player']) assert(labels.includes(l), l);

  // Rename: a global (three places), a local (only inside the function), a field (declaration and the two uses)
  const rename = async (needle, nth, to) => {
    const at = position(source, needle, nth, 0);
    const prepared = await request('textDocument/prepareRename', { textDocument: { uri }, position: at });
    const renamed = await request('textDocument/rename', { textDocument: { uri }, position: at, newName: to });
    return { prepared, renamed };
  };
  let r = await rename('total', 0, 'sum');
  assert.strictEqual(r.renamed.result.changes[uri].length, 4); // Global, two on the line, Print
  assert(applyEdits(source, r.renamed.result.changes[uri]).includes('sum = sum + p\\score'));
  r = await rename('result', 0, 'answer');
  assert.strictEqual(r.renamed.result.changes[uri].length, 2);
  r = await rename('score', 0, 'points');
  assert.strictEqual(r.renamed.result.changes[uri].length, 3);
  assert(applyEdits(source, r.renamed.result.changes[uri]).includes('p\\points = Add(1, 2)'));
  r = await rename('Add', 0, 'Sum');
  assert.strictEqual(r.renamed.result.changes[uri].length, 2);
  // A keyword and a command can't be renamed
  result = await request('textDocument/prepareRename', { textDocument: { uri }, position: position(source, 'Print', 0, 1) });
  assert(result.error, 'Print is a command');
  result = await request('textDocument/rename', { textDocument: { uri }, position: position(source, 'total', 0, 1), newName: 'End' });
  assert(result.error, 'End is a keyword');

  // Rename in a workspace: the file that includes lib.bb and lib.bb change, other.bb does not
  const multi = 'Include "lib.bb"\nPrint shared\nPrint Helper()\n';
  notify('textDocument/didChange', { textDocument: { uri, version: 10 }, contentChanges: [{ text: multi }] });
  diagnostics = await diagnosticsFor(uri);
  assert.deepStrictEqual(diagnostics.filter((d) => d.severity === 1), [], JSON.stringify(diagnostics));
  result = await request('textDocument/rename', { textDocument: { uri }, position: position(multi, 'shared', 0, 1), newName: 'common' });
  const files = Object.keys(result.result.changes).map((u) => path.basename(u)).sort();
  assert.deepStrictEqual(files, ['lib.bb', 'main.bb'], JSON.stringify(result));
  assert.strictEqual(result.result.changes['file://' + path.join(dir, 'lib.bb')].length, 2);

  // Formatting
  const messy = 'If  1=1 Then\nPrint   "x"\n   EndIf\n';
  notify('textDocument/didChange', { textDocument: { uri, version: 2 }, contentChanges: [{ text: messy }] });
  await diagnosticsFor(uri);
  result = await request('textDocument/formatting', { textDocument: { uri }, options: { tabSize: 4, insertSpaces: false } });
  const formatted = applyEdits(messy, result.result);
  assert(/^If 1 = 1 Then\n\tPrint "x"\nEndIf\n$/.test(formatted), JSON.stringify(formatted));

  // Errors: with the position of the compiler, and fixed again by the next change
  notify('textDocument/didChange', { textDocument: { uri, version: 3 }, contentChanges: [{ text: 'Print "a"\nNoSuchCommand(1)\n' }] });
  diagnostics = await diagnosticsFor(uri);
  const error = diagnostics.find((d) => d.severity === 1);
  assert(error && error.range.start.line === 1, JSON.stringify(diagnostics));
  notify('textDocument/didChange', { textDocument: { uri, version: 4 }, contentChanges: [{ text: 'Print "a"\n' }] });
  diagnostics = await diagnosticsFor(uri);
  assert.deepStrictEqual(diagnostics.filter((d) => d.severity === 1), []);

  // Tidy
  notify('textDocument/didChange', { textDocument: { uri, version: 5 }, contentChanges: [{ text: 'Local x% = 1.5\nPrint x\n' }] });
  await diagnosticsFor(uri);
  result = await request('textDocument/codeAction', { textDocument: { uri }, range: { start: { line: 0, character: 0 }, end: { line: 0, character: 0 } }, context: { diagnostics: [], only: ['source.fixAll.blitz'] } });
  assert(Array.isArray(result.result), JSON.stringify(result));
  console.log('tidy actions:', result.result.map((a) => a.title).join(', ') || '(none)');

  result = await request('shutdown', null);
  notify('exit', null);
  child.on('exit', (code) => { console.log('ok'); process.exit(code === 0 ? 0 : 1); });
})().catch((e) => { console.error(e); child.kill(); process.exit(1); });
